class Solution {
public:
    int numberOfWays(int n, int m, int k, vector<int>& source, vector<int>& dest) {
        const long long MOD = 1000000007;
        long long dp[2][2] = {};
        dp[source[0] == dest[0]][source[1] == dest[1]] = 1;
        while (k--) {
            long long nd[2][2] = {};
            for (int r = 0; r < 2; ++r) {
                for (int c = 0; c < 2; ++c) {
                    long long v = dp[r][c];
                    nd[r][c] = (nd[r][c] + v * ((r ? 0 : n - 2) + (c ? 0 : m - 2))) % MOD;
                    nd[1 - r][c] = (nd[1 - r][c] + v * (r ? n - 1 : 1)) % MOD;
                    nd[r][1 - c] = (nd[r][1 - c] + v * (c ? m - 1 : 1)) % MOD;
                }
            }
            memcpy(dp, nd, sizeof dp);
        }
        return dp[1][1];
    }
};
